#include "LegacyPowerSlots.h"
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace aftertaste;using K=MachineKind;using E=EnergyMedium;
static Machine relocated(const Machine& source){auto copy=source;if(copy.kind==K::CoolingPlant)copy.dir=3;return copy;}
static int checks=0;static void require(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}
static Factory empty(){Factory f;f.machines.clear();f.energyLinks.clear();f.blueprints.clear();f.water=f.electricity=10000;return f;}
static Machine& add(Factory& f,Position p,K k,int dir=0){Machine m;m.kind=k;m.dir=dir;initialisePowerDevice(m);return f.machines.emplace(p,m).first->second;}
static void advance(Factory& f,int n){for(int i=0;i<n;i++){f.tick++;f.beginPowerStep();f.finishPowerStep();}}
int main(int argc,char** argv){try{
 {auto f=empty();double total=0;for(int y=0;y<2;y++)for(int x=0;x<3;x++)add(f,{x,y},K::SolarPanel,(x+y)%4);auto& inv=add(f,{3,1},K::Inverter);inv.power.rate=200;advance(f,1);for(const auto& [p,m]:f.machines)if(m.kind==K::SolarPanel)total+=m.power.generated;require(inv.power.store[size_t(E::AC)]>total*.90&&f.energyLinks.empty(),"a rotated two-dimensional six-panel bank aggregates DC across every touching edge without wires");require(f.powerContactFlow({2,1},{3,1},E::DC)>0,"one contact carries the actual array's combined DC output");require(powerContactSupports(K::SolarPanel,K::BatteryRack,E::DC)&&!powerContactSupports(K::SolarPanel,K::Switchboard,E::AC)&&!powerContactSupports(K::SolarPanel,K::QuenchBath,E::Cooling),"panel couplers carry DC without joining unrelated bench services");}
 {auto f=empty();add(f,{0,0},K::SolarPanel);add(f,{1,0},K::SolarPanel);add(f,{2,0},K::SolarPanel);auto& inv=add(f,{3,0},K::Inverter);f.at({1,0})->enabled=false;advance(f,1);double isolated=inv.power.store[size_t(E::AC)];f.at({1,0})->enabled=true;inv.power.store.fill(0);advance(f,1);require(inv.power.store[size_t(E::AC)]>isolated*2,"isolating a panel opens the edge connection to the rest of its row");}
 {auto plan=Factory::powerDistrictBlueprint();require(plan.parts.size()==34,"docking creates no extra yard equipment");for(const auto& link:plan.links)require(link.link.medium!=E::DC&&link.link.medium!=E::Shaft&&link.link.medium!=E::Steam&&link.link.medium!=E::RawGas&&link.link.medium!=E::Gas,"local array, wind, steam, and gas stages dock without intermediate conduits");auto& parts=plan.parts;require(parts[1].at==nextPosition(parts[0].at,0)&&parts[2].at==nextPosition(parts[0].at,1)&&parts[3].at==nextPosition(parts[2].at,0),"demo panels and storage form a touching block");require(parts[8].at==nextPosition(parts[7].at,0)&&parts[9].at==nextPosition(parts[8].at,0),"wind rotor, gearbox and alternator touch");require(parts[14].at==nextPosition(parts[13].at,0)&&parts[15].at==nextPosition(parts[14].at,0)&&parts[16].at==nextPosition(parts[15].at,0),"boiler, accumulator, turbine and alternator touch");require(parts[17].at==nextPosition(parts[28].at,0)&&parts[29].at==nextPosition(parts[17].at,0),"flywheel buffers the engine and alternator directly");}
 {Factory f;f.water=100000;f.farmProduce=10000;f.chemicals=100;bool wind=false,thermal=false,gas=false;for(int n=0;n<240;n++){f.step();for(const auto& [p,m]:f.machines){if(m.kind==K::Alternator&&p.y==powerCampusOrigin.y+3)wind|=m.power.generated>0;if(m.kind==K::SteamTurbine)thermal|=m.power.flow>0;if(m.kind==K::Flywheel)gas|=m.power.store[size_t(E::Shaft)]>0;}}require(wind&&thermal,"docked wind and thermal trains still produce actual work");require(gas,"docked gas engine charges its real flywheel");}
 if(argc>1){std::ifstream in(argv[1]);json j;in>>j;auto before=j.at("factory").get<FactoryState>();Factory f;f.storageFile=argv[1];require(f.load(),"load version 13 yard");auto plan=Factory::powerDistrictBlueprint();std::map<Position,Position> moved;for(size_t n=0;n<legacyPowerSlots.size();n++)moved[{legacyPowerSlots[n].x-27,legacyPowerSlots[n].y-1}]={powerCampusOrigin.x+plan.parts[n].at.x,powerCampusOrigin.y+plan.parts[n].at.y};for(const auto& part:Factory::nuclearLabBlueprint().parts)moved[{nuclearLabOrigin.x+part.at.x,nuclearLabOrigin.y+part.at.y}]={powerCampusLabOrigin.x+part.at.x,powerCampusLabOrigin.y+part.at.y};require(f.machines.size()==before.machines.size(),"saved yard retains its equipment count");for(const auto& [p,m]:before.machines){Position target=moved.count(p)?moved.at(p):p;require(f.at(target)&&json(*f.at(target))==json(relocated(m)),"all original machines keep their settings, live material, charge and readings after docking");}require(f.tick==before.tick&&f.water==before.water&&f.chemicals==before.chemicals&&f.electricity==before.electricity,"yard docking neither spends input buffers nor advances time");
  auto custom=before; // Keep fixture mutations independent of loading.
  for(auto& [p,links]:custom.energyLinks)if(p.x==-25&&p.y==-1)for(auto& l:links)if(l.medium==E::DC)l.rating+=1;auto snapshot=json(custom);require(!dockDefaultPowerDevicesIn(custom)&&json(custom)==snapshot,"custom DC routes and ratings block automatic rearrangement");custom=before;custom.machines[{-25,-1}]=Machine{};snapshot=json(custom);require(!dockDefaultPowerDevicesIn(custom)&&json(custom)==snapshot,"construction in the dock footprint is never overwritten");
  auto file=std::filesystem::temp_directory_path()/"aftertaste-docked-yard.json";f.storageFile=file;require(f.save(),"save docked yard");Factory again;again.storageFile=file;require(again.load()&&json(static_cast<FactoryState&>(again))==json(static_cast<FactoryState&>(f)),"reload cannot move or recharge the yard again");std::filesystem::remove(file);
 }
 std::cout<<"PASS solar and power docking: "<<checks<<" checks\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL power docking: "<<e.what()<<" (check "<<checks<<")\n";return 1;}}
